import re
from pathlib import Path

import pytest

RAIZ = Path(__file__).resolve().parent.parent
CONTRATO = RAIZ / "CONTRATO_PRUEBA_REAL_DOGFOOD.md"
CARPETA_VIGIAS = RAIZ / "vigias"


def _nombres_de_candados(texto):
    seccion = None
    for linea in texto.splitlines():
        if linea.strip().startswith("#") and "Candados" in linea:
            seccion = []
            continue
        if seccion is not None:
            if linea.strip().startswith("#"):
                break
            seccion.append(linea)
    if seccion is None:
        return None
    bloque = "\n".join(seccion)
    nombres = re.findall(r"`(test_vigia[a-zA-Z0-9_]+)`", bloque)
    return nombres


def test_vigia_los_candados_del_contrato_dogfood_existen():
    if not CONTRATO.exists():
        pytest.skip(
            "No encuentro el contrato CONTRATO_PRUEBA_REAL_DOGFOOD.md en la raiz del proyecto, "
            "asi que no puedo comprobar los candados que promete."
        )

    texto = CONTRATO.read_text(encoding="utf-8")
    nombres = _nombres_de_candados(texto)

    if nombres is None:
        pytest.skip(
            "El contrato CONTRATO_PRUEBA_REAL_DOGFOOD.md no tiene una seccion titulada Candados, "
            "asi que no hay candados que comprobar."
        )

    if not nombres:
        pytest.skip(
            "La seccion Candados del contrato no nombra ninguna prueba que empiece por test_vigia, "
            "asi que no hay candados que comprobar."
        )

    faltan = []
    for nombre in nombres:
        nombre_limpio = nombre.strip().strip("`").strip()
        ruta = CARPETA_VIGIAS / (nombre_limpio + ".py")
        if not ruta.exists():
            faltan.append(nombre_limpio)

    if faltan:
        pytest.fail(
            "El contrato promete candados que no existen. Falta el archivo vigias/"
            + " y vigias/".join(faltan)
            + ".py. El contrato esta prometiendo proteccion que no esta."
        )

